import{_ as t,o as e,c as r,a2 as l}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"阿尔·乌尔奇","description":"","frontmatter":{"title":"阿尔·乌尔奇","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/阿尔·乌尔奇.md","filePath":"04_people/阿尔·乌尔奇.md"}'),o={name:"04_people/阿尔·乌尔奇.md"};function i(n,a,s,_,h,c){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="阿尔·乌尔奇-al-urich" tabindex="-1">阿尔·乌尔奇（Al Urich） <a class="header-anchor" href="#阿尔·乌尔奇-al-urich" aria-label="Permalink to &quot;阿尔·乌尔奇（Al Urich）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：飞安国际（FlightSafety）CEO</li><li><strong>与巴菲特关系</strong>：飞安国际被伯克希尔收购后，乌尔奇担任CEO，负责伯克希尔旗下飞行培训业务</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>阿尔·乌尔奇是飞安国际（FlightSafety International）的核心领导者。飞安国际是全球最负盛名的民用及商务航空飞行培训机构之一，为飞行员提供高仿真模拟器培训和认证服务。公司创立于1951年，总部位于纽约，是全球飞行员培训行业的标杆企业。飞安国际以严苛的训练标准和卓越的教学质量著称，为全球各大航空公司和私人飞机运营商培养了无数优秀飞行员。1996年，伯克希尔·哈撒韦收购飞安国际，将其纳入伯克希尔的航空业务板块。乌尔奇在飞安国际担任CEO期间，将公司的培训业务进一步专业化、规模化，确保伯克希尔在航空安全领域的领先地位。飞安国际的高质量培训服务与伯克希尔一贯追求卓越的理念完美契合，是伯克希尔多元化业务组合中不可或缺的组成部分。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1951年</strong>：飞安国际创立，成为美国领先的飞行培训机构</li><li><strong>1996年</strong>：伯克希尔·哈撒韦收购飞安国际，阿尔·乌尔奇继续担任CEO</li><li><strong>1996年后</strong>：在乌尔奇领导下，飞安国际持续扩展训练中心网络，保持行业领先地位</li></ul><hr><p><em>本档案基于公开信息整理，伯克希尔知识库</em></p>',8)])])}const u=t(o,[["render",i]]);export{p as __pageData,u as default};
